#!/usr/bin/env node
/**
 * Way2SA self-contained HTML builder (zero dependencies).
 *
 *   node tools/build.mjs          regenerate every index.html
 *   node tools/build.mjs --check  verify generated files are up to date
 *
 * WHY THIS EXISTS. Shan's content-view renders an HTML file as
 *
 *   <iframe srcDoc={PREVIEW_BRIDGE + fileText} sandbox="allow-scripts">
 *
 * (pkgs/client/content-view/src/file-viewer.tsx). A srcdoc document inherits
 * the APP's base URL, not the file's directory, so `<link href="../assets/x">`
 * and `<script src="data.js">` resolve to Shan routes and 404. The iframe also
 * has an opaque origin (no `allow-same-origin`) and cannot navigate its parent.
 * The only reliable delivery format is ONE document with every asset inlined
 * and every course switch handled in-page. That same document also works over
 * file:// with no server and no build step at read time.
 *
 * Sources of truth stay in assets/ and lessons/*\/data.js; the index.html files
 * are generated artifacts. Never edit them by hand.
 */
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { fileURLToPath, pathToFileURL } from 'node:url';

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const read = p => fs.readFileSync(p, 'utf8');

/** Registry without doing a DOM: curriculum.js only writes to `window`. */
export function curriculum() {
  const s = { window: {} };
  s.window.window = s.window;
  vm.createContext(s);
  vm.runInContext(read(path.join(ROOT, 'assets', 'curriculum.js')), s, { filename: 'curriculum.js' });
  return s.window.CURRICULUM;
}

/* A literal `</script` inside an inline script ends the element. `<\/script`
   is the SAME string to JS but not to the HTML parser. `<!--` would flip the
   parser into escaped script-data state, so it is refused rather than mangled. */
function inlineJs(code, name) {
  if (/<!--/.test(code)) throw new Error(`${name}: contains "<!--"; split the literal before inlining`);
  return code.replace(/<\/script/gi, '<\\/script');
}
function inlineCss(code) {
  return code.replace(/<\/style/gi, '<\\/style');
}
/* JSON inside a <script> must not contain a literal `</script` or `<!--`. */
function jsonForScript(value) {
  return JSON.stringify(value)
    .replace(/<\/script/gi, '<\\/script')
    .replace(/<!--/g, '\\u003C!--')
    .replace(/\u2028/g, '\\u2028')
    .replace(/\u2029/g, '\\u2029');
}

export function targets() {
  const CURR = curriculum();
  const out = [{
    file: 'index.html', initial: 'map', base: '',
    title: 'Way2SA · 从 8 篇原型文档学 Super-agent'
  }];
  for (const c of CURR) {
    out.push({
      file: `${c.dir}/index.html`, initial: c.id, base: '../../',
      title: `${c.id} · ${c.title} | Way2SA`
    });
  }
  return out;
}

export function render(t) {
  const CURR = curriculum();
  const css = inlineCss(read(path.join(ROOT, 'assets', 'course.css')));
  const registry = inlineJs(read(path.join(ROOT, 'assets', 'curriculum.js')), 'curriculum.js');
  // course.js captures WAY2SA_UML at IIFE time, so this must be inlined BEFORE it.
  const uml = inlineJs(read(path.join(ROOT, 'assets', 'uml.js')), 'uml.js');
  const renderer = inlineJs(read(path.join(ROOT, 'assets', 'course.js')), 'course.js');
  const lessons = CURR.map(c =>
    inlineJs(read(path.join(ROOT, c.dir, 'data.js')), `${c.dir}/data.js`)
  );
  /* 讲义 + 教程 both open in-place: a relative href in a srcdoc preview
     resolves to the HOST app, not to lessons/<slug>/README.md. So all eight
     lesson READMEs AND TUTORIALs are inlined; the map's two docs are generated
     from the registry / those tutorials and cost no extra bytes.
     This pushes each page past Shan's 256 KB text chunk. That is fine: for a
     truncated HTML, file-viewer.tsx fetches the whole file once via
     /api/files?type=download (limit 10 MB) and renders it as the same srcdoc. */
  const docs = {};
  for (const c of CURR) docs[c.id] = {
    readme: read(path.join(ROOT, c.dir, 'README.md')),
    tutorial: read(path.join(ROOT, c.dir, 'TUTORIAL.md')),
    // 原型原文 (docs/00x-*.md) opens in the same popup: in a srcdoc preview a
    // link to the file would resolve against the host app, not the repo.
    doc: read(path.join(ROOT, 'dsh-superagent-prototype', 'docs', c.doc))
  };
  const docsScript = 'window.WAY2SA_DOCS=' + jsonForScript(docs) + ';';

  const head = [
    '<!doctype html>',
    '<html lang="zh-CN">',
    '<head>',
    '<meta charset="utf-8">',
    '<meta name="viewport" content="width=device-width, initial-scale=1">',
    `<title>${t.title}</title>`,
    '<!-- GENERATED by tools/build.mjs — edit assets/* and lessons/*/data.js instead -->',
    '<style>',
    css,
    '</style>',
    '</head>',
    '<body>',
    '<div id="app"></div>',
    // Outside #app, so re-rendering a lesson never destroys the open 讲义.
    '<div id="doc-modal" class="modal" style="display:none">',
    '  <div class="modal-head">',
    '    <span class="modal-title" id="doc-title">讲义</span>',
    '    <span class="modal-actions"><button class="btn" id="doc-close" type="button" title="关闭">✕</button></span>',
    '  </div>',
    '  <div class="modal-body" id="doc-body"></div>',
    '</div>',
    // Second popup: clicking a flow-graph block opens its UML class diagram.
    '<div id="uml-modal" class="modal" style="display:none">',
    '  <div class="modal-head">',
    '    <span class="modal-title" id="uml-title">UML</span>',
    '    <span class="modal-actions"><button class="btn" id="uml-close" type="button" title="关闭">✕</button></span>',
    '  </div>',
    '  <div class="modal-body" id="uml-body"></div>',
    '</div>',
    // Set BEFORE course.js runs: it captures BASE, and data.js calls Course.boot().
    `<script>window.WAY2SA_BASE=${JSON.stringify(t.base)};window.WAY2SA_HOLD=true;</script>`,
    `<script>${registry}</script>`,
    `<script>${uml}</script>`,
    `<script>${renderer}</script>`
  ];
  const body = lessons.map(code => `<script>${code}</script>`);
  body.push(`<script>${docsScript}</script>`);
  const tail = [
    `<script>window.WAY2SA_HOLD=false;window.Course.bootCourse(null,${JSON.stringify(t.initial)});</script>`,
    '</body>',
    '</html>',
    ''
  ];
  return [...head, ...body, ...tail].join('\n');
}

function main() {
  const check = process.argv.includes('--check');
  let stale = 0;
  for (const t of targets()) {
    const file = path.join(ROOT, t.file);
    const expected = render(t);
    if (check) {
      const actual = fs.existsSync(file) ? read(file) : '';
      if (actual !== expected) { console.log(`  STALE  ${t.file}`); stale++; }
      else console.log(`  fresh  ${t.file}`);
    } else {
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, expected);
      console.log(`  wrote  ${t.file}  (${(Buffer.byteLength(expected) / 1024).toFixed(1)} KB)`);
    }
  }
  if (check && stale) {
    console.log(`\n${stale} generated file(s) out of date — run: node tools/build.mjs`);
    process.exit(1);
  }
  if (check) console.log('\nOK: every index.html matches its sources.');
  else console.log('\nOK: 9 self-contained HTML files generated (root map + 8 lessons).');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
